'use strict';
const moneyBeforeCleanZero=marketMoney,percentBeforeCleanZero=marketPercent;
marketMoney=value=>moneyBeforeCleanZero(Math.abs(value)<.005?0:value);
marketPercent=value=>percentBeforeCleanZero(value!==null&&Math.abs(value)<.00005?0:value);
let dailyReviewVisible=false;
// Review markers belong to the save, not the currently selected market tab.
function marketReviewState(){let f=financeState();if(f.popupVersion!==1){f.popupVersion=1;f.lastDailyPopup=f.lastReportDay;f.dailyPending=null;}return f;}
const reportBeforeReview=financialDailyReport;
financialDailyReport=function(day){let f=marketReviewState();reportBeforeReview(day);if(f.market?.days>0&&financeUnlocked('broker')&&f.lastReportDay>f.lastDailyPopup){f.dailyPending=f.lastReportDay;save();}};
function maybeDailyMarketReview(){let f=S?.financial;if(!f||modalOpen||draft||bridgeDraft||pointers.size||S.lives<=0)return;if(f.dailyReview){S.paused=true;showFinancialMarket('stocks');return;}if(f.dailyPending==null)return;f.dailyReview={day:f.dailyPending,wasRunning:!S.paused};f.lastDailyPopup=f.dailyPending;f.dailyPending=null;S.paused=true;showFinancialMarket('stocks');save();updateUI();}
function finishDailyMarketReview(){closeModal();updateUI();}
const closeBeforeReview=closeModal;
closeModal=function(){let f=S?.financial,review=f?.dailyReview;if(review&&dailyReviewVisible){delete f.dailyReview;dailyReviewVisible=false;S.paused=review.wasRunning&&S.lives>0?false:true;}else if(f?.marketPause){S.paused=f.marketPause.wasRunning&&S.lives>0?false:true;}if(f)delete f.marketPause;closeBeforeReview();};
function holdingsPanel(){let m=financeState().market;if(!m)return '<p>建设证券公司后开放股票持仓。</p>';let held=m.stocks.map((s,id)=>({s,id,c:MARKET_STOCKS[id]})).filter(x=>x.s.shares>0),cost=held.reduce((n,x)=>n+x.s.cost,0),value=stockValue(),pnl=value-cost;return `<section class="market-holdings"><div class="market-section-title"><div><span class="eyebrow">MY POSITIONS</span><h2>我的持仓</h2></div><span>${held.length} / 15家公司</span></div><div class="market-metrics"><div><small>持仓市值</small><b>${marketMoney(value)}</b></div><div><small>持仓成本</small><b>${marketMoney(cost)}</b></div><div><small>浮动盈亏 / 收益率</small><b class="${pnl>=0?'positive':'negative'}">${marketMoney(pnl)} / ${marketPercent(cost?pnl/cost:0)}</b></div></div>${held.length?held.map(({s,id,c})=>{let profit=s.shares*s.price-s.cost;return `<article class="holding-card"><div class="holding-heading"><button class="holding-name" onclick="marketSelected=${id};showFinancialMarket('stocks')"><b>${c.name}</b><small>${c.industry} · 查看行情 →</small></button><strong class="${profit>=0?'positive':'negative'}">${marketPercent(s.cost?profit/s.cost:0)}</strong></div><dl class="holding-values"><div><dt>持有 / 可卖</dt><dd>${marketShares(s.shares)}</dd></div><div><dt>均价 / 最新价</dt><dd>¥${marketPrice(s.cost/s.shares)} / ¥${marketPrice(s.price)}</dd></div><div><dt>市值 / 浮动盈亏</dt><dd>${marketMoney(s.shares*s.price)} / ${marketMoney(profit)}</dd></div></dl><div class="holding-actions"><label for="holding-qty-${id}">卖出股数<input id="holding-qty-${id}" type="number" inputmode="numeric" min="1" max="${s.shares}" step="1" value="${s.shares}"></label><button class="primary" onclick="sellHolding(${id},false)" ${S.lives<=0?'disabled':''}>卖出</button><button onclick="sellHolding(${id},true)" ${S.lives<=0?'disabled':''}>全部卖出</button></div></article>`;}).join(''):'<div class="holding-empty"><h3>暂未持有股票</h3><p>买入后可在这里查看持股数量、成本和盈亏，并直接卖出。</p><button class="primary" onclick="showFinancialMarket(\'stocks\')">查看股票市场</button></div>'}<p class="market-muted">卖出按当前报价结算，1股起卖，金额向下精确到分。证券公司暂停运营后仍可卖出已有持仓。</p></section>`;}
function sellHolding(id,all){let s=financeState().market?.stocks[id];if(!s)return;tradeStock(id,'sell',all?s.shares:financeInput('holding-qty-'+id));}
const tradeBeforeHoldings=tradeStock;
tradeStock=function(id,side,quantity=financeInput('stock-quantity')){let holdings=marketTab==='holdings';tradeBeforeHoldings(id,side,quantity);if(holdings)showFinancialMarket('holdings');};
const financialViewBeforeHoldings=showFinancialMarket;
showFinancialMarket=function(tab){marketReviewState();if((tab||marketTab)==='holdings'&&!financeUnlocked('broker'))return showFinanceLock('broker');let holdings=(tab||marketTab)==='holdings';financialViewBeforeHoldings(holdings?'portfolio':tab);if(!$('modal-content').innerHTML.includes('financial-market'))return;let f=financeState();if(!f.dailyReview&&!f.marketPause)f.marketPause={wasRunning:!S.paused};S.paused=true;save();let html=$('modal-content').innerHTML;if(holdings){marketTab='holdings';let start=html.indexOf('</nav>')+6;html=html.slice(0,start)+holdingsPanel()+'</div>';html=html.replace(/class="active\s*"/g,'class=""').replace(/aria-pressed="true"/g,'aria-pressed="false"');}html=html.replace('</nav>',`<button class="${holdings?'active':''}" aria-pressed="${holdings}" onclick="showFinancialMarket('holdings')">我的持仓</button></nav>`);let review=S.financial.dailyReview;if(review){dailyReviewVisible=true;html=html.replace('<div class="market-headline">',`<section class="market-daily-banner"><div><b>09:00 · 每日股票简报</b><p>交通工具与主世界已暂停。查看行情或调整持仓后继续。</p></div><button class="primary" onclick="finishDailyMarketReview()">继续交通运行</button></section><div class="market-headline">`);html=html.replace('aria-label="关闭金融市场"','aria-label="关闭并继续交通运行"');}else html=html.replace('<div class="market-headline">','<p class="market-pause-note">金融市场打开期间，主世界与交通工具暂停。</p><div class="market-headline">');$('modal-content').innerHTML=html;};
const renderBeforeDailyReview=render;
render=function(){maybeDailyMarketReview();return renderBeforeDailyReview();};

// A reload starts paused. Reopen a saved daily review after the welcome screen;
// an old manual market window is not an instruction to resume the simulation.
if(S?.financial?.marketPause&&!S.financial.dailyReview)delete S.financial.marketPause;
marketReviewState();
